<!DOCTYPE html>
<html lang="en">
<head>
	<meta charset="UTF-8">
	<meta name="viewport" content="width=device-width, initial-scale=1">
	<link rel="icon" type="image/x-icon" href="data:image/x-icon;base64,">
	<link href="common.css" rel="stylesheet" />
	<title>Starting WordPress</title>
	<style>

		body { 
			display: flex;
			justify-content: center;
			align-items: center; 
		}

		p {
			color: #b0b0b0;
		}

		.card { 
			text-align: center; 
			font-weight: 600;
			padding: 30px 40px;
			border: 1px solid #333;
			border-radius: 12px; 
			box-shadow: 0 4px 20px rgba(0,0,0,0.08); 
			display: flex;
			flex-direction: column;
			align-items: center;
			gap: 20px;
			background: #1e1e1e;
		}

		.card p {
			margin: 0;
			font-size: 1.1em;
		}

		.spinner { 
			margin: 0;
			border: 4px solid #333;
			border-top: 4px solid #0073aa; 
			border-radius: 50%; 
			width: 40px;
			height: 40px;
			animation: spin 1s linear infinite; 
		}

		#subtext {
			font-size: 0.8em;
			font-style: italic;
			font-weight: 400;
			margin: 0 0 0 0;
			opacity: 0.7;
			display: block;
		}

		@keyframes spin {
			0% {
				transform: rotate(0deg);
			}
			100% {
				transform: rotate(360deg);
			}
		}

		@view-transition {
			navigation: auto;
		}

	</style>
	<script>

		document.addEventListener('DOMContentLoaded', (event) => {
			checkReady();
		});

		async function checkReady()
		{
			const startUrl	= '<?php getenv('GP_WORDPRESS_ENDPOINT') ?>/wp-admin/';
			try {
				await fetch(startUrl, { method: 'GET', cache: 'no-store' });
				window.location.href = startUrl;
			}
			catch (e) {
				setTimeout(checkReady, 250);
			}
		}

	</script>
</head>
<body>
	<div class='card'>
		<div class='spinner'></div>
		<p>Starting WordPress</p>
		<p id='subtext'>First launch may take a moment<br>to finalize your WordPress configuration.<br>Subsequent starts will be faster
	</div>
</body>
</html>
